"""causal-learn GIN adapter for data generated by latent variables and their indicators.

Calls ``GIN(X, indep_test_method="hsic", alpha=0.05)``. causal-learn's default test is KCI;
``"hsic"`` selects its gamma-approximation HSIC test, the test Andrey's GIN uses, and ``alpha`` is
both packages' default. The reference is causal-learn with the fix in
``benchmarks/patches/causal-learn-gin-column-index.patch``, which ``benchmarks/patch_causal_learn.sh``
applies; ``setup`` refuses an unpatched install. ``GIN`` returns a graph and the ordered clusters; a cluster it could not
order is in the graph only, as a latent pointing into its members and not in the list. ``fit``
reads both into the native form of :mod:`~andrey_bench.adapters.gin_convert`. The graph names
observed variable ``i`` ``X{i + 1}``, which gives its column.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any, Mapping

import numpy as np

from andrey_bench.adapters.gin_convert import encode_clusters, latent_dag

_DEFAULTS = {"alpha": 0.05, "indep_test_method": "hsic"}


def _causal_learn_version() -> str:
    """The installed causal-learn version (distribution metadata; the module exposes none)."""
    from importlib import metadata

    try:
        return metadata.version("causal-learn")
    except metadata.PackageNotFoundError:  # pragma: no cover - installed in bench-env
        return "unknown"


#: A line only the patched GIN has.
_FIX_MARK = "for z in Z + cluster_i2:"


def _gin_fixed() -> bool:
    """Whether the installed causal-learn GIN carries the column-index fix."""
    from importlib import util

    spec = util.find_spec("causallearn.search.HiddenCausal.GIN.GIN")
    return spec is not None and _FIX_MARK in Path(spec.origin).read_text()


def _reference_version() -> str:
    """The causal-learn version, naming the GIN column-index fix when it is applied."""
    version = _causal_learn_version()
    return f"{version} with the GIN column-index fix" if _gin_fixed() else version


def clusters_of(graph: Any) -> list[list[int]]:
    """Return the cluster of each latent in a causal-learn GIN graph, as column indices."""
    from causallearn.graph.NodeType import NodeType

    clusters = []
    for node in graph.get_nodes():
        if node.get_node_type() != NodeType.LATENT:
            continue
        members = [
            int(child.get_name()[1:]) - 1
            for child in graph.get_children(node)
            if child.get_node_type() != NodeType.LATENT
        ]
        clusters.append(sorted(members))
    return clusters


class CausalLearnGIN:
    """Solution adapter for causal-learn's GIN.

    Satisfies :class:`andrey_bench.contracts.SolutionAdapter`.
    """

    name: str = "causal-learn.gin"
    package: str = "causal-learn"
    package_version: str = _reference_version()
    backend: str = "numpy"
    mode: str = "serial"
    algorithm: str = "gin"
    output_type: str = "dag"

    def setup(self) -> None:
        """Import causal-learn before timing; see `contracts.SetupAdapter`.

        Raises:
            RuntimeError: The installed GIN lacks the column-index fix.
        """
        from causallearn.search.HiddenCausal.GIN.GIN import GIN  # noqa: F401

        if not _gin_fixed():
            raise RuntimeError(
                "causal-learn GIN lacks the column-index fix; run benchmarks/patch_causal_learn.sh"
            )

    def params(self) -> dict[str, Any]:
        """Return the settings passed to ``GIN``."""
        return dict(_DEFAULTS)

    def fit(self, data: np.ndarray, params: Mapping[str, Any]) -> np.ndarray:
        """Run causal-learn GIN; return its clusters and their order. Timed."""
        from causallearn.search.HiddenCausal.GIN.GIN import GIN

        settings = {**_DEFAULTS, **params}
        X = np.asarray(data, dtype=np.float64)
        graph, order = GIN(
            X, indep_test_method=settings["indep_test_method"], alpha=float(settings["alpha"])
        )
        ordered = [sorted(int(i) for i in cluster) for cluster in order]
        unordered = [c for c in clusters_of(graph) if c not in ordered]
        return encode_clusters(ordered, unordered, X.shape[1])

    def to_structure(self, native: np.ndarray) -> Any:
        """Build the latent DAG from the clusters outside the timed region."""
        return latent_dag(native)
